#!/bin/bash\n\n# AnimeHub APK Build Script\n\necho \"🚀 Building AnimeHub APK...\"\n\n# Check if Cordova is installed\nif ! command -v cordova &> /dev/null; then\n    echo \"📦 Installing Cordova globally...\"\n    npm install -g cordova\nfi\n\n# Install dependencies\necho \"📥 Installing dependencies...\"\nnpm install\n\n# Create Cordova project if not exists\nif [ ! -d \"cordova-app\" ]; then\n    echo \"🔧 Creating Cordova project...\"\n    cordova create cordova-app com.animehub.app AnimeHub\n    cd cordova-app\n    cordova platform add android\n    cordova plugin add cordova-plugin-whitelist\n    cordova plugin add cordova-plugin-device\n    cordova plugin add cordova-plugin-network-information\n    cd ..\nfi\n\n# Copy web app to Cordova www directory\necho \"📂 Copying web app files...\"\nrm -rf cordova-app/www/*\ncp -r public/* cordova-app/www/\ncp config.xml cordova-app/\n\n# Copy Cordova-specific index.html\ncat > cordova-app/www/index.html << 'EOF'\n<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, viewport-fit=cover\">\n    <meta name=\"theme-color\" content=\"#1a1a2e\">\n    <title>AnimeHub - Streaming</title>\n    <link rel=\"manifest\" href=\"/manifest.json\">\n    <style>\n        * { margin: 0; padding: 0; box-sizing: border-box; }\n        body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; background: #0f0f1e; color: #e0e0e0; }\n        .header { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%); padding: 10px 15px; display: flex; justify-content: space-between; position: sticky; top: 0; z-index: 100; }\n        .logo { font-size: 18px; font-weight: bold; color: #FF6B6B; }\n        .container { padding: 15px; }\n        .anime-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(120px, 1fr)); gap: 10px; }\n        .anime-card { background: #16213e; border-radius: 8px; cursor: pointer; transition: transform 0.2s; }\n        .anime-card:active { transform: scale(0.98); }\n        .anime-card img { width: 100%; height: 180px; object-fit: cover; }\n        main { padding-bottom: 70px; }\n        .bottom-nav { position: fixed; bottom: 0; left: 0; right: 0; background: #16213e; display: flex; justify-content: space-around; padding: 10px 0; z-index: 50; }\n        .bottom-nav button { background: none; border: none; color: rgba(224,224,224,0.6); cursor: pointer; padding: 10px; font-size: 12px; }\n        .bottom-nav button.active { color: #FF6B6B; }\n    </style>\n</head>\n<body>\n    <header class=\"header\">\n        <div class=\"logo\">🎬 AnimeHub</div>\n        <div style=\"display: flex; gap: 15px;\">\n            <button style=\"background: none; border: none; color: #e0e0e0; font-size: 18px;\">🔔</button>\n            <button style=\"background: none; border: none; color: #e0e0e0; font-size: 18px;\">👤</button>\n        </div>\n    </header>\n\n    <main class=\"container\">\n        <section class=\"home-section\">\n            <h2 style=\"font-size: 18px; margin: 20px 0 10px; color: #FF6B6B;\">🔥 Trending</h2>\n            <div id=\"trendingGrid\" class=\"anime-grid\"></div>\n        </section>\n        <section class=\"home-section\">\n            <h2 style=\"font-size: 18px; margin: 20px 0 10px; color: #FF6B6B;\">✨ Recommended</h2>\n            <div id=\"recommendedGrid\" class=\"anime-grid\"></div>\n        </section>\n    </main>\n\n    <nav class=\"bottom-nav\">\n        <button class=\"nav-item active\">🏠 Home</button>\n        <button class=\"nav-item\">🔍 Search</button>\n        <button class=\"nav-item\">📚 List</button>\n        <button class=\"nav-item\">👤 Profile</button>\n    </nav>\n\n    <script type=\"text/javascript\" src=\"cordova.js\"></script>\n    <script>\n        const API_URL = 'http://your-server-ip:3000/api';\n\n        document.addEventListener('deviceready', onDeviceReady, false);\n\n        function onDeviceReady() {\n            console.log('Cordova is ready');\n            loadTrending();\n        }\n\n        async function loadTrending() {\n            try {\n                const res = await fetch(`${API_URL}/anime/trending`);\n                const anime = await res.json();\n                renderGrid('trendingGrid', anime);\n            } catch (err) {\n                console.error('Error:', err);\n            }\n        }\n\n        function renderGrid(elementId, anime) {\n            const grid = document.getElementById(elementId);\n            grid.innerHTML = anime.map(a => `\n                <div class=\"anime-card\">\n                    <img src=\"${a.thumbnail_url || '/placeholder.jpg'}\" alt=\"${a.title}\" loading=\"lazy\">\n                    <div style=\"padding: 8px;\">\n                        <div style=\"font-size: 12px; font-weight: 600; color: #e0e0e0;\">${a.title}</div>\n                        <div style=\"font-size: 10px; color: rgba(224,224,224,0.6);\">${a.total_episodes || '?'} eps</div>\n                    </div>\n                </div>\n            `).join('');\n        }\n    </script>\n</body>\n</html>\nEOF\n\n# Build APK\necho \"🔨 Building APK (this may take 5-10 minutes)...\"\ncd cordova-app\ncordova build android --release\ncd ..\n\n# Check if build succeeded\nif [ -f \"cordova-app/platforms/android/app/build/outputs/apk/release/app-release-unsigned.apk\" ]; then\n    echo \"✅ APK build successful!\"\n    echo \"📦 APK Location: cordova-app/platforms/android/app/build/outputs/apk/release/app-release-unsigned.apk\"\n    echo \"\"\n    echo \"📝 Next steps:\"\n    echo \"1. Sign the APK using your keystore\"\n    echo \"2. Align the APK\"\n    echo \"3. Upload to Google Play Store or distribute directly\"\nelse\n    echo \"❌ APK build failed. Check logs above for errors.\"\n    exit 1\nfi\n\necho \"🎉 Build complete!\"\n